// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    // fuzz: amount to deposit/withdraw and an arbitrary actor address (fuzzer supplies)
    function testFuzz_property(uint256 amount, address actor) public {
        // keep amount in a reasonable range but wide so fuzzer can find issues
        amount = bound(amount, 1, 1 ether);
        // actor must not be zero address
        vm.assume(actor != address(0));

        // deploy a reentrant attacker that will call back into c during withdraw
        ReentrantAttacker attacker = new ReentrantAttacker(address(c));

        // fund the attacker externally so it can deposit and receive refunds
        vm.deal(address(attacker), amount);

        // attacker deposits `amount` into c as its credit
        attacker.deposit{value: amount}();

        // Now attempt withdrawAll from attacker: it will re-enter if mutant allows
        bool ok;
        try attacker.callWithdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // General property: after withdrawAll returns, the contract's recorded credit for attacker must be zero.
        // We observe this via the public withdrawAll behavior: since credit is private we can't call a getter,
        // but we can assert that a second withdrawAll call from the same attacker transfers nothing (i.e., does not send value).
        // We implement that by recording attacker's balance before/after a second withdraw call; on the correct contract,
        // the second withdraw should not increase the attacker's balance.

        // capture attacker's balance
        uint256 balBefore = address(attacker).balance;
        // attempt second withdraw; it should do nothing (succeed but not transfer value)
        try attacker.callWithdrawAll() {
            // nothing
        } catch {
            // ignore reverts
        }
        uint256 balAfter = address(attacker).balance;

        // The invariant: balAfter == balBefore (no additional funds transferred on second withdraw)
        // This holds for the reference C for all inputs; the mutant that moves credit[msg.sender]=0 before the call
        // can allow reentrancy to modify state so that this equality can be violated for some inputs.
        assertTrue(balAfter == balBefore);
    }
}

// Minimal reentrant attacker: deposits to C and on receiving funds (in receive) tries to re-enter withdrawAll once.
contract ReentrantAttacker {
    C c;
    bool reentered;
    constructor(address _c) {
        c = C(_c);
        reentered = false;
    }

    // deposit helper
    function deposit() external payable {
        // forward deposit to c
        (bool ok, ) = address(c).call{value: msg.value}(abi.encodeWithSignature("deposit()"));
        require(ok);
    }

    // call withdrawAll from this contract
    function callWithdrawAll() external {
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        require(ok);
    }

    // receive will try to re-enter withdrawAll once
    receive() external payable {
        if (!reentered) {
            reentered = true;
            // attempt reentrant call
            // ignore success/failure
            (bool , ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: depositor address and deposit amount
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep depositor as a valid address, not zero
        vm.assume(depositor != address(0));
        // bound amount to a reasonable range so vm.deal works and to avoid overflow in test harness
        amount = bound(amount, 1, 1 ether);

        // deploy an adversarial reentrant attacker that will receive funds and re-enter withdrawAll
        // This is necessary because raw EOA addresses always succeed on .call and cannot re-enter
        ReentrantAttacker attacker = new ReentrantAttacker(c);

        // fund depositor and attacker so they can deposit and attacker can receive refunds
        vm.deal(depositor, amount);
        vm.deal(address(attacker), 1 ether);

        // depositor deposits into c
        vm.prank(depositor);
        c.deposit{value: amount}();

        // record contract balance before withdraw
        uint256 before = address(c).balance;

        // Now have depositor set the attacker's address as msg.sender by using attacker to call withdraw
        // We want to simulate attacker being the caller who has credit; so first let attacker deposit
        vm.prank(address(attacker));
        c.deposit{value: amount}();

        // attacker will attempt withdrawAll; if contract is vulnerable (mutant), reentrancy can alter final balance
        bool ok;
        try attacker.doWithdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: after withdrawAll completes, the contract's balance must be exactly before - amount
        // (the attacker had deposited `amount` and withdrew `amount`). The correct contract ensures this for all inputs;
        // the mutant can be re-entered and break this equality for some inputs.
        assertTrue(address(c).balance == before - amount);
    }
}

// Minimal reentrant attacker: on receive, it tries to call withdrawAll again
contract ReentrantAttacker {
    C public target;
    uint public entered;
    constructor(C _t) {
        target = _t;
    }
    // deposit helper
    function doWithdraw() external {
        target.withdrawAll();
    }
    receive() external payable {
        // only re-enter once to try to exploit ordering differences
        if (entered == 0) {
            entered = 1;
            // re-enter
            target.withdrawAll();
        }
    }
}

