pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: depositor (actor) and amount to deposit/withdraw
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep depositor as a non-zero address and amount in a practical range
        vm.assume(depositor != address(0));
        uint256 amt = bound(amount, 1, 1e24); // allow wide but bounded amounts

        // fund the depositor so they can deposit and attacker can receive refunds
        vm.deal(depositor, amt);

        // depositor makes a deposit to c
        vm.prank(depositor);
        c.deposit{value: amt}();

        // record initial contract balance
        uint256 initialBalance = address(c).balance;

        // deploy a reentrant attacker that will call withdrawAll when receiving funds
        ReentrantAttacker attacker = new ReentrantAttacker(address(c));

        // credit the attacker by having it deposit
        vm.deal(address(attacker), amt);
        attacker.deposit{value: amt}();

        // ensure attacker is the one calling withdrawAll; it will try to reenter within receive()
        bool ok;
        try attacker.callWithdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: for the reference C (with reentrancy lock), a single withdrawAll
        // invocation by the attacker can at most withdraw once, leaving the contract balance
        // decreased exactly by amt. Therefore address(c).balance == initialBalance - amt must hold.
        // We assert that property (this passes on the reference and is violated by the mutant).
        assertTrue(address(c).balance == initialBalance - amt);
    }
}

// Minimal reentrant attacker: on receiving funds it attempts to reenter withdrawAll once.
contract ReentrantAttacker {
    C public target;
    bool public reentered;
    constructor(address _target) payable {
        target = C(_target);
    }

    function deposit() external payable {
        // deposit into target
        target.deposit{value: msg.value}();
    }

    // initiate withdrawAll from this contract
    function callWithdrawAll() external {
        target.withdrawAll();
    }

    receive() external payable {
        // attempt reentrancy only once
        if (!reentered) {
            reentered = true;
            // attempt to call withdrawAll again during the external call
            // if the target has a reentrancy lock (reference), this will revert or fail
            // if not (mutant), this may succeed and drain extra funds
            // we ignore any revert here
            try target.withdrawAll() {
            } catch {
            }
        }
    }
}

