pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: amount to deposit and a boolean that decides whether caller is a contract (we always use a contract adversary)
    function testFuzz_property(uint256 amount, uint256 seed) public {
        // keep amount in a reasonable range but wide
        amount = bound(amount, 1, 1 ether);

        // deploy a depositor contract that will revert when receiving funds
        Reverter reverter = new Reverter();

        // fund the depositor so it can call deposit
        vm.deal(address(reverter), amount);

        // have the reverter deposit into c
        vm.prank(address(reverter));
        reverter.callDeposit{value: amount}(address(c));

        // now the reverter (which will revert on receiving ETH) will call withdrawAll
        // we expect the correct contract's withdrawAll to complete (not revert) for any inputs
        bool ok;
        try reverter.callWithdraw(address(c)) {
            ok = true;
        } catch {
            ok = false;
        }

        // single assertion: for the reference C, withdrawAll() invoked by a reverting contract never reverts
        assertTrue(ok);
    }
}

// adversarial helper: will revert in receive(), simulating a callee that fails the external call
contract Reverter {
    // allow this contract to call deposit on C
    function callDeposit(address c) external payable {
        (bool success, ) = c.call{value: msg.value}(abi.encodeWithSignature("deposit()"));
        require(success);
    }

    // call withdrawAll on C; the external transfer from C to this contract will trigger receive() which reverts
    function callWithdraw(address c) external {
        (bool success, ) = c.call(abi.encodeWithSignature("withdrawAll()"));
        require(success);
    }

    receive() external payable {
        revert("I always revert on receive");
    }
}
